package com.saga.be.service.ai; import com.saga.be.dto.ai.AiAcademicClassificationResponse; import com.saga.be.entity.ai.AiAcademicClassification; import com.saga.be.entity.enums.AiArtifactType; import com.saga.be.repository.AiAcademicClassificationRepository; import com.saga.be.service.projection.ProjectDataAuthorization; import java.util.*; import org.springframework.context.annotation.Profile; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional;
@Service @Profile("!test") public class AiAcademicClassificationRepositoryFacade {private final AiAcademicClassificationRepository repo;private final ProjectDataAuthorization auth;public AiAcademicClassificationRepositoryFacade(AiAcademicClassificationRepository r,ProjectDataAuthorization a){repo=r;auth=a;}@Transactional(readOnly=true) public List<AiAcademicClassificationResponse> history(UUID user,UUID project,AiArtifactType type,UUID artifact){auth.requireReader(user,project);return repo.findHistory(project,type,artifact).stream().map(this::map).toList();} public AiAcademicClassificationResponse map(AiAcademicClassification c){boolean p=c.getTargetType()==com.saga.be.entity.enums.AiAcademicTargetType.PHASE;return new AiAcademicClassificationResponse(c.getId(),c.getArtifactType().name(),c.getArtifactId(),c.getArtifactRevision(),c.getSyllabusVersion().getId(),c.getTargetType().name(),p?c.getPhase().getId():c.getDeliverable().getId(),p?c.getPhase().getCode():c.getDeliverable().getCode(),p?c.getPhase().getName():c.getDeliverable().getName(),c.getConfidence(),c.getAiSummary(),c.getStatus().name(),c.getProvenance().name(),c.getSourceClassification()==null?null:c.getSourceClassification().getId(),c.getReviewedAt(),c.getCreatedAt());}}
